if(!specs.length)specs.push({id:'self',kind:'empty',R:2.4,side:0});
const kinds={};view.items.forEach(item=>kinds[item.key]=item.kind);
const E=view.lanes.map(l=>({from:l.from,to:l.to,kind:l.kind,port:l.ports.join(', '),io:l.kind==='entry'||kinds[l.from]==='external'||kinds[l.to]==='external',dash:l.kind==='implements'||l.kind==='hole'}));
const islands=view.items.filter(item=>item.kind==='island');const maxL=islands.length?Math.max(...islands.map(item=>item.level)):0;sc.maxL=maxL;
// level height: LV up to 6 levels, then the stack keeps the height of 6
